     1	import getFullTreeByParentUid from "roamjs-components/queries/getFullTreeByParentUid";
     2	import { OnloadArgs, TreeNode } from "roamjs-components/types";
     3	import { MAX_WIDTH } from "~/components/canvas/Tldraw";
     4	import { measureCanvasNodeText } from "./measureCanvasNodeText";
     5	import resolveQueryBuilderRef from "./resolveQueryBuilderRef";
     6	import runQuery from "./runQuery";
     7	import getDiscourseNodes from "./getDiscourseNodes";
     8	import resolveRefs from "roamjs-components/dom/resolveRefs";
     9	import { render as renderToast } from "roamjs-components/components/Toast";
    10	import { loadImage } from "./loadImage";
    11	import { DEFAULT_STYLE_PROPS } from "~/components/canvas/DiscourseNodeUtil";
    12	
    13	const extractFirstImageUrl = (text: string): string | null => {
    14	  const regex = /!\[.*?\]\((https:\/\/[^)]+)\)/;
    15	  const result = text.match(regex) || resolveRefs(text).match(regex);
    16	  return result ? result[1] : null;
    17	};
    18	
    19	// Matches embed, embed-path, and embed-children syntax:
    20	// {{[[embed]]: ((block-uid)) }}, {{[[embed-path]]: ((block-uid)) }}, {{[[embed-children]]: ((block-uid)) }}
    21	// Also handles multiple parentheses: {{[[embed]]: ((((block-uid)))) }}
    22	const EMBED_REGEX =
    23	  /{{\[\[(?:embed|embed-path|embed-children)\]\]:\s*\(\(+([^)]+?)\)+\)\s*}}/i;
    24	
    25	const getBlockReferences = (
    26	  uid: string,
    27	): { ":block/uid"?: string; ":block/string"?: string }[] => {
    28	  const result =
    29	    (window.roamAlphaAPI?.pull?.(
    30	      "[:block/uid {:block/refs [:block/uid :block/string]}]",
    31	      [":block/uid", uid],
    32	    ) as {
    33	      [":block/refs"]?: { ":block/uid"?: string; ":block/string"?: string }[];
    34	    } | null) || {};
    35	  return result[":block/refs"] || [];
    36	};
    37	
    38	const findFirstImage = (
    39	  node: TreeNode,
    40	  visited = new Set<string>(),
    41	): string | null => {
    42	  if (visited.has(node.uid)) return null;
    43	  visited.add(node.uid);
    44	
    45	  const imageUrl = extractFirstImageUrl(node.text);
    46	  if (imageUrl) return imageUrl;
    47	
    48	  const embedUid = node.text.match(EMBED_REGEX)?.[1];
    49	  if (embedUid && !visited.has(embedUid)) {
    50	    const embedTree = getFullTreeByParentUid(embedUid);
    51	    const embedImageUrl = findFirstImage(embedTree, visited);
    52	    if (embedImageUrl) return embedImageUrl;
    53	  }
    54	
    55	  const references = getBlockReferences(node.uid);
    56	  for (const reference of references) {
    57	    const referenceText = reference[":block/string"] || "";
    58	    const referenceImage = extractFirstImageUrl(referenceText);
    59	    if (referenceImage) return referenceImage;
    60	  }
    61	
    62	  if (node.children) {
    63	    for (const child of node.children) {
    64	      const childImageUrl = findFirstImage(child, visited);
    65	      if (childImageUrl) return childImageUrl;
    66	    }
    67	  }
    68	
    69	  return null;
    70	};
    71	
    72	const getFirstImageByUid = (uid: string): string | null => {
    73	  const tree = getFullTreeByParentUid(uid);
    74	  return findFirstImage(tree);
    75	};
    76	
    77	const calcCanvasNodeSizeAndImg = async ({
    78	  nodeText,
    79	  uid,
    80	  nodeType,
    81	  extensionAPI,
    82	}: {
    83	  nodeText: string;
    84	  uid: string;
    85	  nodeType: string;
    86	  extensionAPI: OnloadArgs["extensionAPI"];
    87	}) => {
    88	  const allNodes = getDiscourseNodes();
    89	  const canvasSettings = Object.fromEntries(
    90	    allNodes.map((n) => [n.type, { ...n.canvasSettings }]),
    91	  );
    92	  const {
    93	    "query-builder-alias": qbAlias = "",
    94	    "key-image": isKeyImage = "",
    95	    "key-image-option": keyImageOption = "",
    96	  } = canvasSettings[nodeType] || {};
    97	
    98	  const { w, h } = measureCanvasNodeText({
    99	    ...DEFAULT_STYLE_PROPS,
   100	    maxWidth: MAX_WIDTH,
   101	    text: nodeText,
   102	  });
   103	
   104	  if (!isKeyImage) return { w, h, imageUrl: "" };
   105	
   106	  let imageUrl;
   107	  if (keyImageOption === "query-builder") {
   108	    const parentUid = resolveQueryBuilderRef({ queryRef: qbAlias });
   109	    const results = await runQuery({
   110	      extensionAPI,
   111	      parentUid,
   112	      inputs: { NODETEXT: nodeText, NODEUID: uid },
   113	    });
   114	    const resultUid = results.allProcessedResults[0]?.uid || "";
   115	    imageUrl = getFirstImageByUid(resultUid);
   116	  } else {
   117	    imageUrl = getFirstImageByUid(uid);
   118	  }
   119	  if (!imageUrl) return { w, h, imageUrl: "" };
   120	
   121	  try {
   122	    const { width, height } = await loadImage(imageUrl);
   123	    if (
   124	      !width ||
   125	      !height ||
   126	      !Number.isFinite(width) ||
   127	      !Number.isFinite(height)
   128	    ) {
   129	      return { w, h, imageUrl: "" };
   130	    }
   131	
   132	    const aspectRatio = width / height;
   133	    const nodeImageHeight = w / aspectRatio;
   134	    const newHeight = h + nodeImageHeight;
   135	
   136	    return { w, h: newHeight, imageUrl };
   137	  } catch {
   138	    renderToast({
   139	      id: "tldraw-image-load-fail",
   140	      content: "Failed to load image",
   141	      intent: "warning",
   142	    });
   143	    return { w, h, imageUrl: "" };
   144	  }
   145	};
   146	
   147	export default calcCanvasNodeSizeAndImg;

